-- Disposable database only. Every fixture rolls back.
begin;
create function pg_temp.assert_true(ok boolean,label text) returns void language plpgsql as $$
begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end $$;
create function pg_temp.expect_error(statement text,expected text) returns void language plpgsql as $$
begin begin execute statement;exception when others then if sqlstate=expected then return;end if;raise;end;raise exception 'Expected SQLSTATE %',expected;end $$;
insert into auth.users(id,email) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','one@example.invalid'),('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','two@example.invalid'),('cccccccc-cccc-4ccc-8ccc-cccccccccccc','outside@example.invalid');
create temporary table conversation_context(key text primary key,value text);
grant select,insert,update on conversation_context to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',true);
insert into conversation_context values('child',(public.create_family_v2('Ava','UTC')).id::text),('invite',public.create_family_invite());
create function pg_temp.converse(op text,p jsonb,r uuid default gen_random_uuid()) returns jsonb language sql as $$
 select public.execute_care_conversation((select value::uuid from conversation_context where key='child'),r,repeat('a',64),op,now(),'siri',p,'UTC',0,jsonb_build_array(jsonb_build_object('from',now()-interval '366 days','seconds',0)),'en');
$$;
create function pg_temp.record(t text,v numeric default null,d text default null) returns jsonb language sql as $$
 select jsonb_build_object('action','record','payload',jsonb_build_object('event_type',t,'occurred_at',now()-interval '1 minute','volume_ml',v,'diaper_kind',d,'weight_kg',null));
$$;
insert into conversation_context values('batch',pg_temp.converse('batch',jsonb_build_object('actions',jsonb_build_array(pg_temp.record('feeding',100),pg_temp.record('diaper',null,'wet'))),'dddddddd-dddd-4ddd-8ddd-dddddddddddd')::text);
select pg_temp.assert_true((select count(*) from public.events)=2,'batch persists both events');
select pg_temp.assert_true(jsonb_array_length((select value::jsonb->'event_ids' from conversation_context where key='batch'))=2,'batch returns both persisted IDs');
select pg_temp.converse('batch',jsonb_build_object('actions',jsonb_build_array(pg_temp.record('feeding',100),pg_temp.record('diaper',null,'wet'))),'dddddddd-dddd-4ddd-8ddd-dddddddddddd');
select pg_temp.assert_true((select count(*) from public.events)=2,'outer retry never duplicates batch');
insert into conversation_context values('receipts_before',(select count(*)::text from public.care_receipts));
select pg_temp.assert_true((pg_temp.converse('query',jsonb_build_object('kind','day_summary','day',current_date))->'details'->>'feeding_ml')::numeric=100,'query uses actual persisted intake');
select pg_temp.assert_true((select count(*)::text from public.care_receipts)=(select value from conversation_context where key='receipts_before'),'questions do not create receipts or events');
select pg_temp.assert_true((pg_temp.converse('query','{"kind":"last_feeding","day":null}')->'details'->>'value')::numeric=100,'last feeding query returns correct amount');
select pg_temp.assert_true(pg_temp.converse('batch',jsonb_build_object('actions',jsonb_build_array(pg_temp.record('feeding',50),jsonb_build_object('action','sleep_end','payload',jsonb_build_object('occurred_at',now())))))->>'status'='needs_clarification','missing sleep start clarifies whole batch');
select pg_temp.assert_true((select count(*) from public.events)=2 and (select count(*)::text from public.care_receipts)=(select value from conversation_context where key='receipts_before'),'later failure rolls back earlier event and inner receipts');
insert into conversation_context values('proposal',pg_temp.converse('correct','{"selector":{"kind":"feeding","expected_volume_ml":100},"changes":{"correction_kind":"total","amount_ml":80},"remove":false}')->>'proposal_id');
select pg_temp.assert_true((select volume_ml=100 from public.events where event_type='feeding'),'voice correction only proposes');
select pg_temp.assert_true((select message not like '%{%"%' from public.care_proposals where id=(select value::uuid from conversation_context where key='proposal')),'confirmation contains no raw JSON');
select pg_temp.converse('action',jsonb_build_object('action','cancel','payload',jsonb_build_object('proposal_id',(select value from conversation_context where key='proposal'))));
select pg_temp.assert_true((select volume_ml=100 from public.events where event_type='feeding'),'cancel leaves feeding unchanged');
select pg_temp.assert_true(pg_temp.converse('correct','{"selector":{"kind":"feeding","expected_volume_ml":30},"changes":{"correction_kind":"total","amount_ml":80},"remove":false}')->>'status'='needs_clarification','from amount mismatch never retargets record');
update conversation_context set value=pg_temp.converse('correct','{"selector":{"kind":"feeding","expected_volume_ml":100},"changes":{"correction_kind":"total","amount_ml":80},"remove":false}')->>'proposal_id' where key='proposal';
select pg_temp.converse('action',jsonb_build_object('action','confirm','payload',jsonb_build_object('proposal_id',(select value from conversation_context where key='proposal'))));
select pg_temp.assert_true((select volume_ml=80 and revision=2 from public.events where event_type='feeding'),'confirmed voice correction updates original record once');
update conversation_context set value=pg_temp.converse('correct','{"selector":{"kind":"diaper","diaper_kind":"wet"},"changes":{"diaper_kind":"dirty"},"remove":false}')->>'proposal_id' where key='proposal';
select pg_temp.assert_true((select diaper_kind='wet' from public.events where event_type='diaper'),'diaper stays wet before confirmation');
select pg_temp.converse('action',jsonb_build_object('action','confirm','payload',jsonb_build_object('proposal_id',(select value from conversation_context where key='proposal'))));
select pg_temp.assert_true((select diaper_kind='dirty' and revision=2 from public.events where event_type='diaper'),'diaper type changes in place after confirmation');
select pg_temp.converse('batch',jsonb_build_object('actions',jsonb_build_array(pg_temp.record('diaper',null,'mixed'))));
select pg_temp.assert_true(pg_temp.converse('query',jsonb_build_object('kind','wet_count','day',current_date))->'details'->>'wet_count'='1','mixed diaper contributes once to wet');
select pg_temp.assert_true(pg_temp.converse('query',jsonb_build_object('kind','dirty_count','day',current_date))->'details'->>'dirty_count'='2','mixed diaper contributes once to dirty');
update conversation_context set value=pg_temp.converse('correct','{"selector":{"kind":"diaper","diaper_kind":"mixed"},"changes":{},"remove":true}')->>'proposal_id' where key='proposal';
select pg_temp.assert_true((select count(*) from public.events)=3,'delete is proposal only');
select pg_temp.converse('action',jsonb_build_object('action','confirm','payload',jsonb_build_object('proposal_id',(select value from conversation_context where key='proposal'))));
select pg_temp.assert_true((select count(*) from public.events)=2,'confirmed deletion removes only qualifying diaper from reads');
select pg_temp.assert_true(pg_temp.converse('query',jsonb_build_object('kind','wet_count','day',current_date))->'details'->>'wet_count'='0','deleted record excluded from counts');
insert into conversation_context values('time_proposal',pg_temp.converse('correct',jsonb_build_object('selector',jsonb_build_object('kind','diaper'),'changes',jsonb_build_object('occurred_at',now()-interval '20 minutes'),'remove',false))->>'proposal_id');
select pg_temp.assert_true((select position(to_char(now()-interval '20 minutes','HH12:MI AM') in message)>0 from public.care_proposals where id=(select value::uuid from conversation_context where key='time_proposal')),'time-only correction shows replacement time before confirmation');
select pg_temp.converse('action',jsonb_build_object('action','milestone','payload',jsonb_build_object('title','Smiled at a familiar face','occurred_on',current_date,'date_precision','day')));
insert into conversation_context values('guide',pg_temp.converse('action',jsonb_build_object('action','milestone','payload',jsonb_build_object('title','Smiled at a familiar face','occurred_on',current_date,'date_precision','day','guide_id','cdc-2-smile')))->>'event_id');
select pg_temp.assert_true((select count(*) from public.milestones where guide_id='cdc-2-smile')=1,'guide checkoff persists stable identity');
select set_config('request.jwt.claim.sub','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',true);
select public.join_family((select value from conversation_context where key='invite'));
select pg_temp.converse('action',jsonb_build_object('action','milestone','payload',jsonb_build_object('title','Smiled at a familiar face','occurred_on',current_date,'date_precision','day','guide_id','cdc-2-smile')));
select pg_temp.assert_true((select count(*) from public.milestones)=2 and (select count(*) from public.milestones where guide_id is null)=1,'guide checkoff keeps existing free-text memory intact and never duplicates guide identity');
select pg_temp.expect_error($q$select pg_temp.converse('query',jsonb_build_object('kind','wet_count','day',current_date+1))$q$,'22023');
select pg_temp.expect_error($q$select pg_temp.converse('batch','{"actions":[]}')$q$,'22023');
select pg_temp.expect_error($q$select pg_temp.converse('correct','{"selector":{"kind":"diaper"},"changes":{"weight_kg":8},"remove":false}')$q$,'22023');
select pg_temp.converse('action',jsonb_build_object('action','sleep_interval','payload',jsonb_build_object('occurred_at',now()-interval '50 minutes','ended_at',now()-interval '20 minutes')));
select pg_temp.assert_true((pg_temp.converse('query',jsonb_build_object('kind','sleep_total','day',current_date))->'details'->>'sleep_minutes')::numeric=greatest(0,round(extract(epoch from ((now()-interval '20 minutes')-greatest(now()-interval '50 minutes',current_date::timestamptz)))/60)),'query includes completed sleep clipped at midnight');
insert into conversation_context values('sleep_batch',pg_temp.converse('batch',jsonb_build_object('actions',jsonb_build_array(jsonb_build_object('action','sleep_start','payload',jsonb_build_object('occurred_at',now()-interval '10 minutes')),jsonb_build_object('action','sleep_end','payload',jsonb_build_object('occurred_at',now()-interval '5 minutes')))))::text);
select pg_temp.assert_true(jsonb_array_length((select value::jsonb->'event_ids' from conversation_context where key='sleep_batch'))=1,'start and wake in one description return one unique persisted session ID');

select pg_temp.assert_true(pg_temp.converse('query',jsonb_build_object('kind','last_weight','day',null))->'details'->>'has_records'='false','missing weight is no recorded measurement, not a zero weight');
select pg_temp.converse('action',jsonb_build_object('action','record','payload',jsonb_build_object('event_type','weight','occurred_at',now()-interval '1 minute','weight_kg',7.1,'volume_ml',null,'diaper_kind',null,'measurement_date',current_date-2)));
select pg_temp.assert_true(pg_temp.converse('query',jsonb_build_object('kind','last_weight','day',current_date-2))->'details'->>'has_records'='true','weight day question uses measurement date rather than internal timestamp');
select pg_temp.expect_error($q$select pg_temp.converse('action','{"action":"milestone","payload":{"title":"Injected guide","occurred_on":"2026-01-01","date_precision":"day","is_first":false,"guide_id":"arbitrary"}}')$q$,'22023');
select set_config('request.jwt.claim.sub','cccccccc-cccc-4ccc-8ccc-cccccccccccc',true);
select pg_temp.expect_error($q$select pg_temp.converse('query','{"kind":"day_summary","day":null}')$q$,'42501');
select pg_temp.expect_error($q$select pg_temp.converse('correct','{"selector":{"kind":"diaper"},"changes":{},"remove":true}')$q$,'42501');
select pg_temp.expect_error($q$select pg_temp.converse('batch','{"actions":[] }')$q$,'42501');
reset role;
select pg_temp.assert_true((select count(*) from public.events where voided_at is not null)=1,'deleted diaper retained for audit');
select pg_temp.assert_true(not has_function_privilege('anon','public.execute_care_conversation(uuid,uuid,text,text,timestamptz,public.input_source,jsonb,text,integer,jsonb,text)','EXECUTE'),'anonymous cannot execute conversation RPC');
rollback;
